WITH valid AS (SELECT *, CASE WHEN level IN ('L1', 'L5') THEN 'Priority' ELSE 'Other' END AS level_group FROM employees WHERE hire_date >= DATE '2023-07-21'), latest AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY dept_id, manager_id ORDER BY salary, id) AS latest_rank FROM valid) ranked WHERE latest_rank = 1), deduped AS (SELECT * FROM latest QUALIFY ROW_NUMBER() OVER (PARTITION BY dept_id, job_title ORDER BY salary, id) = 1), deduped_employees AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY dept_id, job_title ORDER BY latest_rank DESC, id) AS dedup_rank FROM deduped) t WHERE dedup_rank = 1), ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY job_title ORDER BY latest_rank, id) AS rn FROM deduped_employees QUALIFY rn = 1) SELECT dept_id, SUM(CASE WHEN level = 'L4' THEN salary ELSE 0 END) AS l4_salary, MAX(salary) AS max_salary, SUM(salary) AS total_salary, PERCENTILE_APPROX(salary, ARRAY(0.25, 0.5, 0.75)) AS salary_quartiles, SUM(salary) AS total_salary_2, ROUND(AVG(salary), 2) AS avg_salary FROM ranked GROUP BY 1 ORDER BY total_salary DESC NULLS FIRST
